// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address depositor, uint256 amount) public {
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1e18);

        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.addToBalance{value: amount}();

        Reverter r = new Reverter();

        vm.deal(address(r), amount);
        vm.prank(address(r));
        c.addToBalance{value: amount}();

        bool ok;
        try c.withdrawBalance{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.getBalance(address(r)) == 0);
        } else {
            assertTrue(c.getBalance(address(r)) == amount);
        }
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert on receive");
    }
    receive() external payable {
        revert("revert on receive");
    }
}
